insert into public.regulatory_citations(entity_type,entity_id,instrument,article,source_type,citation_url,published_date,accessed_date,excerpt) select 'pathway',rp.id,'Regulation No. 495 of 26 May 2026 on controlled substances',null,'regulator','https://www.logir.fo/Bekendtgorelse/495-af-26-05-2026-for-Faeroerne-om-euforiserende-stoffer','2026-05-26',current_date,'Cannabis is listed in the controlled-substance schedules; Lists B, D and E are for medical and scientific use and authorization rules apply.' from public.regulatory_pathways rp where rp.iso_alpha2='FO' and rp.slug='depth-v1-fo' and not exists(select 1 from public.regulatory_citations rc where rc.entity_id=rp.id);
insert into public.regulatory_citations(entity_type,entity_id,instrument,article,source_type,citation_url,published_date,accessed_date,excerpt) select 'pathway',rp.id,'Inatsisartut Act No. 24 of 25 November 2022 / Regulation No. 61 of 22 August 2025',null,'regulator','https://nalunaarutit.gl/groenlandsk-lovgivning/2025/selvstyrets-bekendtgørelse-nr-61-af-01_09_2025?sc_lang=da',null,current_date,'Greenland controlled-substance rules govern cannabis within an authorization-based medical/scientific framework.' from public.regulatory_pathways rp where rp.iso_alpha2='GL' and rp.slug='depth-v1-gl' and not exists(select 1 from public.regulatory_citations rc where rc.entity_id=rp.id);
