on conflict (source_url) do update set is_active=true,jurisdiction_code=excluded.jurisdiction_code,tier=excluded.tier,notes=excluded.notes,updated_at=now();
update public.regulatory_market_access_evidence set tier='medical_limited_trade',rationale=case when jurisdiction_iso2='FO' then 'Faroe Islands Regulation No. 495 of 26 May 2026 lists cannabis in the controlled-substance schedules; the regulation states Lists B, D and E are for medical and scientific use and provides permit rules for medical cultivation/distribution. No general adult-use commercial retail pathway is established by this instrument.' else 'Greenland Act No. 24 of 25 November 2022 establishes that controlled substances may be restricted to medical or scientific use; the 2025 self-government regulation governs controlled substances and includes cannabis. Commercial adult-use cannabis is not established by the cited framework; permitted medical/scientific activity remains subject to authorization.' end,authority_name=case when jurisdiction_iso2='FO' then 'Lógasavn / Faroe Islands — Regulation No. 495 of 26 May 2026 on controlled substances' else 'Greenland Self-Government — Regulation No. 61 of 22 August 2025 on controlled substances' end,authority_url=case when jurisdiction_iso2='FO' then 'https://www.logir.fo/Bekendtgorelse/495-af-26-05-2026-for-Faeroerne-om-euforiserende-stoffer' else 'https://nalunaarutit.gl/groenlandsk-lovgivning/2025/selvstyrets-bekendtgørelse-nr-61-af-01_09_2025?sc_lang=da' end,verified_at=now(),expires_at=now()+interval '1 year' where jurisdiction_iso2 in ('FO','GL') and active;
on conflict (claim_key) do update set claim_text=excluded.claim_text,authority_name=excluded.authority_name,authority_url=excluded.authority_url,verified_at=excluded.verified_at,expires_at=excluded.expires_at,evidence_status='verified',updated_at=now();
on conflict(country_code) do update set public_summary=excluded.public_summary,commercial_pathway_summary=excluded.commercial_pathway_summary,review_status=excluded.review_status,regulatory_tier=excluded.regulatory_tier,last_reviewed_at=excluded.last_reviewed_at,last_enriched_at=excluded.last_enriched_at,updated_at=now();
select c.id,'FO','depth-v1-fo','Faroe Islands medical/scientific cannabis authorization pathway','medical_access_program','Faroe Islands Regulation No. 495 of 26 May 2026 on controlled substances','Faroe Islands / Danish Medicines Agency framework','active','2026-05-26','Cannabis is controlled and authorized activity is limited to the medical/scientific framework described in the regulation; no general adult-use retail pathway is established by the cited instrument.',null,array['https://www.logir.fo/Bekendtgorelse/495-af-26-05-2026-for-Faeroerne-om-euforiserende-stoffer'],'needs_review',null,array[]::text[],null,null,null from public.countries c where c.iso_alpha2='FO' on conflict (slug) do nothing;
select c.id,'GL','depth-v1-gl','Greenland controlled-substance medical/scientific pathway','medical_access_program','Inatsisartut Act No. 24 of 25 November 2022 and Greenland Self-Government Regulation No. 61 of 22 August 2025 on controlled substances','Greenland Self-Government / Landslægeembedet','active',null,'Cannabis is included in Greenland’s controlled-substance framework. Medical/scientific use and specified import activity require authorization; no general adult-use commercial retail pathway is established by the cited framework.',null,array['https://nalunaarutit.gl/groenlandsk-lovgivning/2022/l-24-2022?sc_lang=da','https://nalunaarutit.gl/groenlandsk-lovgivning/2025/selvstyrets-bekendtgørelse-nr-61-af-01_09_2025?sc_lang=da'],'needs_review',null,array[]::text[],null,null,null from public.countries c where c.iso_alpha2='GL' on conflict (slug) do nothing;
update public.regulatory_pathways set verification='verified',last_verified_at=now(),updated_at=now() where slug in ('depth-v1-fo','depth-v1-gl');
update public.jurisdiction_data_depth_tasks set status='verified',updated_at=now() where dimension_key='country_intel' and jurisdiction_key in ('EH','FK','FO','GL','HK','PR','SC');
